interface OrbitOrb {
  gfx: Phaser.GameObjects.Graphics;
  angle: number;
  speed: number;    // rad/ms (음수 = 반시계)
  radius: number;
  tiltCos: number;  // 궤도 기울기 (작을수록 납작한 타원)
}

// 각 궤도 고유 파라미터 — 전자 궤도처럼 방향/기울기/속도 다양화
const ORBIT_CONFIGS: { speed: number; radius: number; tiltCos: number; startAngle: number }[] = [
  {  speed:  0.0020, radius: 38, tiltCos: 0.32, startAngle: 0 },
  {  speed: -0.0017, radius: 41, tiltCos: 0.58, startAngle: Math.PI * 0.7 },
  {  speed:  0.0024, radius: 36, tiltCos: 0.44, startAngle: Math.PI * 1.3 },
  {  speed: -0.0015, radius: 43, tiltCos: 0.22, startAngle: Math.PI * 0.4 },
  {  speed:  0.0019, radius: 39, tiltCos: 0.78, startAngle: Math.PI * 1.7 },
];

