private _createRevivalHalo(scene: Phaser.Scene, x: number, y: number): void {
  const hy = y - 38; // 머리 위 위치

  // 외곽 부드러운 글로우
  this.revivalHaloOuter = scene.add.image(x, hy, 'glow_dot')
    .setDepth(3)
    .setBlendMode(Phaser.BlendModes.ADD)
    .setTint(0xffffff)
    .setScale(2.2)
    .setAlpha(0.35);

  // 내부 약간 따뜻한 글로우
  this.revivalHaloInner = scene.add.image(x, hy, 'glow_dot')
    .setDepth(4)
    .setBlendMode(Phaser.BlendModes.ADD)
    .setTint(0xffeedd)
    .setScale(1.1)
    .setAlpha(0.65);

  scene.tweens.add({
    targets: this.revivalHaloOuter,
    alpha: { from: 0.2, to: 0.55 },
    scale: { from: 2.0, to: 2.5 },
    yoyo: true, repeat: -1, duration: 1100, ease: 'Sine.easeInOut',
  });
  scene.tweens.add({
    targets: this.revivalHaloInner,
    alpha: { from: 0.45, to: 0.80 },
    yoyo: true, repeat: -1, duration: 1100, ease: 'Sine.easeInOut',
  });
}

