145	  private _updateYeoijus(api: GameSceneAPI): void {
146	    const delta = api.scene.game.loop.delta * 0.001;
147	    const { player } = api;
148	    const fallDelta = (api.baseSpeed + api.difficultyLevel * 40) * delta;
149	    const r2 = MUGI_PARAMS.yeoijuCollectRadius ** 2;
150	    const remaining: YeoijuOrb[] = [];
151	
152	    for (const orb of this.yeoijus) {
153	      orb.y += fallDelta;
154	      orb.gfx.setPosition(orb.x, orb.y);
155	
156	      const dx = player.x - orb.x;
157	      const dy = player.y - orb.y;
158	      if (dx * dx + dy * dy < r2) {
159	        this._collectYeoiju(orb, api);
160	        continue;
161	      }
162	      if (orb.y > 660) { orb.gfx.destroy(); continue; }
163	      remaining.push(orb);
164	    }
165	    this.yeoijus = remaining;
166	  }
