205	  private _tickAura(api: GameSceneAPI): void {
206	    const level = this.isGoldForm ? 4 : Math.floor(this.yeoijuCount / 10);
207	    const delta = api.scene.game.loop.delta;
208	
209	    // 레벨별 검은/금색 기운
210	    if (level > 0) {
211	      this.auraTimer += delta;
212	      const interval = Math.max(70, 400 - level * 70);
213	      if (this.auraTimer >= interval) {
214	        this.auraTimer -= interval;
215	        const color = this.isGoldForm ? 0xffdd00 : 0x8800ff;
216	        for (let i = 0; i < level; i++) {
217	          this._spawnAuraWisp(api.player.x, api.player.y, color, level, api.scene);
218	        }
219	      }
220	    }
221	
222	  }
