375	  // applyGoldSprite: true → 변신 시 (180ms 딜레이 후 gold 텍스처 적용), false → 이미 변신 상태
376	  private _strikeThunder(api: GameSceneAPI, applyGoldSprite: boolean): void {
377	    const { scene, player } = api;
378	    const tx = player.x;
379	    const ty = player.y;
380	
381	    if (applyGoldSprite) scene.cameras.main.flash(600, 80, 70, 0, true);
382	
383	    const g = scene.add.graphics().setDepth(310);
384	
385	    const makePts = (startX: number) => {
386	      const pts: { x: number; y: number }[] = [{ x: startX, y: -10 }];
387	      for (let i = 1; i < 17; i++) {
388	        const t = i / 17;
389	        const spread = 70 * (1 - t * 0.65);
390	        pts.push({ x: tx + Phaser.Math.Between(-spread, spread), y: (ty + 20) * t - 10 });
391	      }
392	      pts.push({ x: tx, y: ty + 8 });
393	      return pts;
394	    };
395	
396	    const drawBolt = () => {
397	      g.clear();
398	      const pts = makePts(tx + Phaser.Math.Between(-25, 25));
399	      g.lineStyle(44, 0xffaa00, 0.09); this._drawPolyline(g, pts);
400	      g.lineStyle(22, 0xffcc00, 0.32); this._drawPolyline(g, pts);
401	      g.lineStyle(9,  0xffee44, 0.80); this._drawPolyline(g, pts);
402	      g.lineStyle(3,  0xffffff, 1.00); this._drawPolyline(g, pts);
403	      [3, 7, 11].forEach(bi => {
404	        if (bi >= pts.length - 1) return;
405	        const bp = pts[bi]!;
406	        const dir = Math.random() < 0.5 ? 1 : -1;
407	        const len = Phaser.Math.Between(55, 105);
408	        const bPts = [
409	          { x: bp.x, y: bp.y },
410	          { x: bp.x + dir * len * 0.35 + Phaser.Math.Between(-18, 18), y: bp.y + len * 0.33 },
411	          { x: bp.x + dir * len * 0.68 + Phaser.Math.Between(-12, 12), y: bp.y + len * 0.65 },
412	          { x: bp.x + dir * len + Phaser.Math.Between(-8, 8),          y: bp.y + len },
413	        ];
414	        g.lineStyle(9,   0xffcc00, 0.40); this._drawPolyline(g, bPts);
415	        g.lineStyle(3,   0xffee44, 0.75); this._drawPolyline(g, bPts);
416	        g.lineStyle(1.5, 0xffffff, 0.90); this._drawPolyline(g, bPts);
417	      });
418	    };
419	
420	    drawBolt();
421	    [50, 100, 150, 200].forEach(delay => {
422	      scene.time.delayedCall(delay, () => {
423	        if (!scene.sys.isActive() || !g.active) return;
424	        drawBolt();
425	      });
426	    });
427	
428	    scene.tweens.add({
429	      targets: g, alpha: 0, delay: 240, duration: 380, ease: 'Quad.easeOut',
430	      onComplete: () => g.destroy(),
431	    });
432	
433	    const impact = scene.add.graphics().setDepth(308);
434	    impact.fillStyle(0xffee00, 0.7);
435	    impact.fillCircle(tx, ty, 55);
436	    scene.tweens.add({
437	      targets: impact, scaleX: 2.8, scaleY: 2.8, alpha: 0,
438	      duration: 500, ease: 'Quad.easeOut',
439	      onComplete: () => impact.destroy(),
440	    });
441	
442	    const ring = scene.add.graphics().setDepth(309);
443	    ring.lineStyle(4, 0xffffff, 1);
444	    ring.strokeCircle(tx, ty, 40);
445	    scene.tweens.add({
446	      targets: ring, scaleX: 3.5, scaleY: 3.5, alpha: 0,
447	      duration: 450, ease: 'Quad.easeOut',
448	      onComplete: () => ring.destroy(),
449	    });
450	
451	    scene.time.delayedCall(180, () => {
452	      if (!scene.sys.isActive()) return;
453	      // 변신 도중 부활로 isGoldForm이 해제됐을 수 있으므로 확인
454	      if (applyGoldSprite && this.isGoldForm) {
455	        api.player.setTexturePrefix('gold_mugi_');
456	      }
457	      this._clearPoops(api, () => true, 20);
458	    });
459	  }
