486	      g.lineStyle(30, 0x440000, 0.09); this._drawPolyline(g, pts);
487	      g.lineStyle(14, 0x880000, 0.32); this._drawPolyline(g, pts);
488	      g.lineStyle(6,  0x080000, 0.92); this._drawPolyline(g, pts); // 코어 바로 외곽 — 진한 검정
489	      g.lineStyle(2,  0xff3311, 1.00); this._drawPolyline(g, pts);
490	      [3, 7, 11].forEach(bi => {
491	        if (bi >= pts.length - 1) return;
492	        const bp = pts[bi]!;
493	        const dir = Math.random() < 0.5 ? 1 : -1;
494	        const len = Phaser.Math.Between(55, 105);
495	        const bPts = [
496	          { x: bp.x, y: bp.y },
497	          { x: bp.x + dir * len * 0.35 + Phaser.Math.Between(-18, 18), y: bp.y + len * 0.33 },
498	          { x: bp.x + dir * len * 0.68 + Phaser.Math.Between(-12, 12), y: bp.y + len * 0.65 },
499	          { x: bp.x + dir * len + Phaser.Math.Between(-8, 8),          y: bp.y + len },
500	        ];
501	        g.lineStyle(6,   0x880000, 0.40); this._drawPolyline(g, bPts);
502	        g.lineStyle(2,   0x080000, 0.88); this._drawPolyline(g, bPts);
503	        g.lineStyle(1,   0xff3311, 0.90); this._drawPolyline(g, bPts);
504	      });
505	    };
506	
507	    drawRed();
508	    [55, 110, 165].forEach(delay => {
509	      scene.time.delayedCall(delay, () => {
510	        if (!scene.sys.isActive() || !g.active) return;
511	        drawRed();
512	      });
