537	  private _clearPoops(
538	    api: GameSceneAPI,
539	    filter: (p: Phaser.Physics.Arcade.Sprite) => boolean,
540	    pointsPerPoop: number,
541	  ): void {
542	    const { poops, scene } = api;
543	    const targets = (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
544	      .filter(p => p.active && filter(p));
545	
546	    if (targets.length === 0) return;
547	
548	    // 위치를 먼저 저장한 뒤 즉시 재활용 — 피버 타임이 얼어있는 똥을
549	    // 특수 똥으로 변환하는 race condition을 원천 차단
550	    const positions = targets.map(p => ({ x: p.x, y: p.y }));
551	    targets.forEach(p => (p as unknown as PoolablePoopBase).recycle());
552	
553	    // 잽 이펙트는 저장된 위치에서 독립적으로 재생
554	    positions.forEach(({ x, y }) => this._spawnZapEffect(x, y, scene));
