628	  private _playRevivalLotus(px: number, py: number, scene: Phaser.Scene): void {
629	    const LS = 2.2;                // 연꽃 전체 스케일
630	    const cx = px;
631	    const cy = py + 38;            // 플레이어 발 바닥 (displayH=80 → 중심 +40, base offset -2)
632	
633	    // 꽃받침
634	    const base = scene.add.graphics().setDepth(352).setScale(0);
635	    base.fillStyle(0x66bb6a, 0.85); base.fillEllipse(0, 0, 28 * LS, 9 * LS);
636	    base.fillStyle(0x81c784, 0.6);  base.fillEllipse(0, -2 * LS, 16 * LS, 5 * LS);
637	    base.setPosition(cx, cy + 2);
638	    scene.tweens.add({ targets: base, scale: 1, duration: 220, ease: 'Back.easeOut' });
639	
640	    // 금빛 중앙 글로우
641	    const glow = scene.add.graphics().setDepth(353).setScale(0);
642	    glow.fillStyle(0xffd700, 0.20); glow.fillCircle(0, 0, 30 * LS);
643	    glow.fillStyle(0xffe082, 0.35); glow.fillCircle(0, 0, 18 * LS);
644	    glow.fillStyle(0xffffff, 0.55); glow.fillCircle(0, 0,  8 * LS);
645	    glow.setPosition(cx, cy - 14 * LS);
646	    scene.tweens.add({ targets: glow, scale: 1, duration: 320, ease: 'Back.easeOut' });
647	
648	    // sin(t*π) 곡선으로 양 끝 뾰족한 꽃잎 폴리곤
649	    const petalPts = (w: number, h: number): { x: number; y: number }[] => {
650	      const N = 16;
651	      const pts: { x: number; y: number }[] = [];
652	      for (let i = 0; i <= N; i++) {
653	        const t = i / N;
654	        pts.push({ x:  (w / 2) * Math.sin(t * Math.PI), y: h / 2 - t * h });
655	      }
656	      for (let i = N - 1; i >= 0; i--) {
657	        const t = i / N;
658	        pts.push({ x: -(w / 2) * Math.sin(t * Math.PI), y: h / 2 - t * h });
659	      }
660	      return pts;
661	    };
662	
663	    // 꽃잎: 바닥 한 점에서 각도 방향으로 뻗어나가는 옆면 형태
664	    const petalGfxs: Phaser.GameObjects.Graphics[] = [];
665	    LOTUS_DEFS.forEach(([rotDeg, w, h, color, depthOff], idx) => {
666	      const sw = w * LS;
667	      const sh = h * LS;
668	      const rotRad = rotDeg * Math.PI / 180;
669	      const ppx = cx + Math.sin(rotRad) * (sh / 2);
670	      const ppy = (cy + 2) - Math.cos(rotRad) * (sh / 2);
671	
672	      const g = scene.add.graphics().setDepth(353 + depthOff);
673	      g.fillStyle(color, 0.92);
674	      g.fillPoints(petalPts(sw, sh), true);
675	      g.fillStyle(0xffffff, 0.45);
676	      g.fillPoints(petalPts(sw * 0.35, sh * 0.65), true);
677	      g.fillStyle(0xffd700, 0.18);
678	      g.fillEllipse(0, -(sh * 0.3), sw * 0.55, sh * 0.22);
679	      g.setPosition(ppx, ppy).setRotation(rotRad).setScale(0);
680	
681	      scene.tweens.add({ targets: g, scale: 1, delay: idx * 40, duration: 280, ease: 'Back.easeOut' });
682	      petalGfxs.push(g);
683	    });
684	
685	    // 수술
686	    const stamen = scene.add.graphics().setDepth(359).setScale(0);
687	    stamen.fillStyle(0xffd700, 1); stamen.fillCircle(0, 0, 5 * LS);
688	    stamen.fillStyle(0xffff99, 0.9); stamen.fillCircle(0, 0, 3 * LS);
689	    stamen.fillStyle(0xffffff, 0.7); stamen.fillCircle(-1 * LS, -1.5 * LS, 1.5 * LS);
690	    stamen.setPosition(cx, cy - 20 * LS);
691	    scene.tweens.add({
692	      targets: stamen, scale: 1,
693	      delay: LOTUS_DEFS.length * 40 - 20, duration: 220, ease: 'Back.easeOut',
694	    });
695	
696	    // 900ms 후 조용히 페이드아웃
697	    const allObjs: Phaser.GameObjects.Graphics[] = [...petalGfxs, glow, base, stamen];
698	    scene.time.delayedCall(900, () => {
699	      if (!scene.sys.isActive()) return;
700	      allObjs.forEach(obj => {
701	        scene.tweens.add({
702	          targets: obj, alpha: 0,
703	          duration: 500, ease: 'Quad.easeIn',
704	          onComplete: () => { if (obj.active) obj.destroy(); },
705	        });
706	      });
707	    });
708	  }
