1	import Phaser from 'phaser';
2	import { BaseAbility } from './BaseAbility';
3	import type { GameSceneAPI } from './types';
4	import type PoolablePoopBase from '../objects/PoolablePoopBase';
5	import { MUGI_PARAMS } from '../config/abilityParams';
6	import { ensureGlowDot } from '../utils/glowDot';
7	
8	// 옆면 연꽃 꽃잎 정의: [rotDeg, width, height, color, depthOffset]
9	// 꽃잎 바닥이 한 점에 모이고 각도 방향으로 뻗어나가는 형태
10	const LOTUS_DEFS: [number, number, number, number, number][] = [
11	  [ -68, 11, 30, 0xfff8e1, 0 ],
12	  [  68, 11, 30, 0xfff8e1, 0 ],
13	  [ -46, 10, 27, 0xfffde7, 1 ],
14	  [  46, 10, 27, 0xfffde7, 1 ],
15	  [ -26,  9, 24, 0xffffff, 2 ],
16	  [  26,  9, 24, 0xffffff, 2 ],
17	  [ -10,  8, 21, 0xffffff, 3 ],
18	  [  10,  8, 21, 0xffffff, 3 ],
19	  [   0,  7, 18, 0xffffff, 4 ],
20	];
21	
22	interface YeoijuOrb {
23	  gfx: Phaser.GameObjects.Graphics;
24	  x: number;
25	  y: number;
26	}
27	
28	interface OrbitOrb {
29	  gfx: Phaser.GameObjects.Graphics;
30	  angle: number;
31	  speed: number;    // rad/ms (음수 = 반시계)
32	  radius: number;
33	  tiltCos: number;  // 궤도 기울기 (작을수록 납작한 타원)
34	}
35	
36	// 각 궤도 고유 파라미터 — 전자 궤도처럼 방향/기울기/속도 다양화
37	const ORBIT_CONFIGS: { speed: number; radius: number; tiltCos: number; startAngle: number }[] = [
38	  {  speed:  0.0050, radius: 30, tiltCos: 0.32, startAngle: 0 },
39	  {  speed: -0.0043, radius: 32, tiltCos: 0.58, startAngle: Math.PI * 0.7 },
40	  {  speed:  0.0060, radius: 29, tiltCos: 0.44, startAngle: Math.PI * 1.3 },
41	  {  speed: -0.0038, radius: 34, tiltCos: 0.22, startAngle: Math.PI * 0.4 },
42	  {  speed:  0.0048, radius: 31, tiltCos: 0.78, startAngle: Math.PI * 1.7 },
43	];
44	
45	export class MugiAbility extends BaseAbility {
46	  private lastYeoijuScore    = 0;
47	  private yeoijuCount        = 0;
48	  private yeoijus: YeoijuOrb[] = [];
49	  private orbitOrbs: OrbitOrb[] = [];
50	  private counterText: Phaser.GameObjects.Text | null = null;
51	  private normalPrefix     = 'mugi_';
52	  private isGoldForm       = false;
53	  private auraTimer        = 0;
54	  private revivalHaloOuter: Phaser.GameObjects.Image | null = null;
55	  private revivalHaloInner: Phaser.GameObjects.Image | null = null;
56	
57	  // Revival state
58	  private revivalCharges     = 1;   // 0 or 1 (max stored)
59	  private totalRevivalsUsed  = 0;   // lifetime cap: 3
60	  private revivalChargeCount = 0;   // yeoijus collected toward recharge
61	  private revivalText: Phaser.GameObjects.Text | null = null;
62	
63	  override onCreate(api: GameSceneAPI): void {
64	    this.lastYeoijuScore    = 0;
65	    this.yeoijuCount        = 0;
66	    this.yeoijus            = [];
67	    this.orbitOrbs          = [];
68	    this.counterText        = null;
69	    this.normalPrefix       = api.player.getTexturePrefix();
70	    this.isGoldForm         = false;
71	    this.auraTimer          = 0;
72	    this.revivalHaloOuter   = null;
73	    this.revivalHaloInner   = null;
74	    this.revivalCharges     = 1;
75	    ensureGlowDot(api.scene);
76	    this._createRevivalHalo(api);
77	    this.totalRevivalsUsed  = 0;
78	    this.revivalChargeCount = 0;
79	    this.revivalText        = null;
80	
81	    this.counterText = api.scene.add.text(8, 80, `여의주 0/${MUGI_PARAMS.goldThreshold}`, {
82	      fontSize: '11px',
83	      color: '#ff88cc',
84	      stroke: '#000000',
85	      strokeThickness: 3,
86	    }).setDepth(500).setAlpha(0.88);
87	
88	    this.revivalText = api.scene.add.text(8, 95, '♡ 부활', {
89	      fontSize: '11px',
90	      color: '#ff66bb',
91	      stroke: '#000000',
92	      strokeThickness: 3,
93	    }).setDepth(500).setAlpha(0.88);
94	  }
95	
96	  override onScoreMilestone(score: number, api: GameSceneAPI): void {
97	    const interval = this.isGoldForm ? MUGI_PARAMS.yeoijuGoldInterval : MUGI_PARAMS.yeoijuInterval;
98	    if (score % interval === 0 && score > this.lastYeoijuScore) {
99	      this.lastYeoijuScore = score;
100	      this._spawnYeoiju(api);
101	    }
102	  }
103	
104	  override onUpdate(api: GameSceneAPI): void {
105	    this._updateYeoijus(api);
106	    this._tickAura(api);
107	    this._updateOrbitOrbs(api);
108	    this._updateRevivalHalo(api.player.x, api.player.y);
109	  }
110	
111	  override onHitPoop(api: GameSceneAPI): boolean {
112	    if (this.revivalCharges > 0 && this.totalRevivalsUsed < 3) {
113	      this._revive(api);
114	      return true;
115	    }
116	    return false;
117	  }
118	
119	  // ── 여의주 ──────────────────────────────────────────────────────────
120	
121	  private _spawnYeoiju(api: GameSceneAPI): void {
122	    const scene = api.scene;
123	    const x = Phaser.Math.Between(30, 370);
124	
125	    const gfx = scene.add.graphics().setDepth(150);
