127	    gfx.fillStyle(0x550000, 1);    gfx.fillCircle(0, 0, 11);
128	    // 내부 광원 — 중앙 살짝 아래 오프셋 (속에서 빛나는 느낌)
129	    gfx.fillStyle(0xaa1100, 0.95); gfx.fillCircle(1, 2, 8);
130	    gfx.fillStyle(0xdd2200, 0.80); gfx.fillCircle(1, 2, 5);
131	    gfx.fillStyle(0xff5500, 0.55); gfx.fillCircle(1, 3, 2.5);
132	    // 반사 하이라이트 — 왼쪽 위 (구슬 3D 효과)
133	    gfx.fillStyle(0xffffff, 0.90); gfx.fillCircle(-3.5, -3.5, 2.5);
134	    gfx.fillStyle(0xffffff, 0.40); gfx.fillCircle(-2.5, -5, 1);
135	    gfx.setPosition(x, -20);
136	
137	    scene.tweens.add({
138	      targets: gfx, alpha: { from: 0.72, to: 1 },
139	      yoyo: true, repeat: -1, duration: 720, ease: 'Sine.easeInOut',
140	    });
