145	  private _updateYeoijus(api: GameSceneAPI): void {
146	    const delta = api.scene.game.loop.delta * 0.001;
147	    const { player } = api;
148	    const fallDelta = (api.baseSpeed + api.difficultyLevel * 40) * delta;
149	    const r2 = MUGI_PARAMS.yeoijuCollectRadius ** 2;
150	    const remaining: YeoijuOrb[] = [];
151	
152	    for (const orb of this.yeoijus) {
153	      orb.y += fallDelta;
154	      orb.gfx.setPosition(orb.x, orb.y);
155	
156	      const dx = player.x - orb.x;
157	      const dy = player.y - orb.y;
158	      if (dx * dx + dy * dy < r2) {
159	        this._collectYeoiju(orb, api);
160	        continue;
161	      }
162	      if (orb.y > 660) { orb.gfx.destroy(); continue; }
163	      remaining.push(orb);
164	    }
165	    this.yeoijus = remaining;
166	  }
167	
168	  private _collectYeoiju(orb: YeoijuOrb, api: GameSceneAPI): void {
169	    this._spawnCollectEffect(orb.x, orb.y, api.scene);
170	    orb.gfx.destroy();
171	    api.addAbilityBonus(80);
172	
173	    // Revival recharge: runs regardless of gold form
174	    if (this.revivalCharges === 0 && this.totalRevivalsUsed < 3) {
175	      this.revivalChargeCount++;
176	      if (this.revivalChargeCount >= MUGI_PARAMS.goldThreshold) {
177	        this.revivalCharges = 1;
178	        this.revivalChargeCount = 0;
179	        this._playRechargeGlow(api);
180	      }
181	      this._updateRevivalUI();
182	    }
183	
184	    if (this.isGoldForm) {
185	      this._strikeThunder(api, false);
186	      return;
187	    }
188	
189	    this.yeoijuCount++;
190	    this._updateCounter();
191	
192	    if (this.yeoijuCount % 10 === 0 && this.orbitOrbs.length < 5) {
193	      this._spawnOrbitOrb(api);
194	    }
195	
196	    if (this.yeoijuCount >= MUGI_PARAMS.goldThreshold) {
197	      this._transformGold(api);
198	    } else {
199	      this._strikeRedLightning(api);
200	    }
201	  }
