224	  // glow_dot + ADD 블렌드로 여우불 질감 표현
225	  private _spawnAuraWisp(px: number, py: number, color: number, level: number, scene: Phaser.Scene): void {
226	    const angle  = Math.random() * Math.PI * 2;
227	    const spread = 18 + level * 4;
228	    const ox = px + Math.cos(angle) * Phaser.Math.Between(8, spread);
229	    const oy = py + Math.sin(angle) * Phaser.Math.Between(8, spread * 0.6);
230	    const sz  = Phaser.Math.FloatBetween(3, 5 + level * 0.6);
231	    const glowScale = sz / 28;
232	
233	    // 외곽 글로우 (ADD 블렌드 — 뒤 화면색에 색을 더함)
234	    const img = scene.add.image(ox, oy, 'glow_dot')
235	      .setDepth(6)
236	      .setBlendMode(Phaser.BlendModes.ADD)
237	      .setTint(color)
238	      .setScale(glowScale);
239	
240	    // 코어: 흰색 glow_dot으로 중심 강조 (Graphics → Image, 드로우콜 제거)
241	    const core = scene.add.image(ox, oy, 'glow_dot')
242	      .setDepth(7)
243	      .setBlendMode(Phaser.BlendModes.ADD)
244	      .setTint(0xffffff)
245	      .setScale(glowScale * 0.32);
246	
247	    const tx  = ox + Phaser.Math.Between(-14, 14);
248	    const ty  = oy - Phaser.Math.Between(22, 44);
249	    const dur = Phaser.Math.Between(480, 860);
250	
251	    scene.tweens.add({
252	      targets: img, x: tx, y: ty, alpha: 0, scale: glowScale * 0.3,
253	      duration: dur, ease: 'Quad.easeOut',
254	      onComplete: () => { if (img.active) img.destroy(); },
255	    });
256	    scene.tweens.add({
257	      targets: core, x: tx, y: ty, alpha: 0, scale: 0,
258	      duration: dur, ease: 'Quad.easeOut',
259	      onComplete: () => { if (core.active) core.destroy(); },
260	    });
261	  }
