366	  private _strikeThunder(api: GameSceneAPI, applyGoldSprite: boolean): void {
367	    const { scene, player } = api;
368	    const tx = player.x;
369	    const ty = player.y;
370	
371	    if (applyGoldSprite) scene.cameras.main.flash(600, 80, 70, 0, true);
