377	      for (let i = 1; i < 17; i++) {
378	        const t = i / 17;
379	        const spread = 70 * (1 - t * 0.65);
380	        pts.push({ x: tx + Phaser.Math.Between(-spread, spread), y: (ty + 20) * t - 10 });
381	      }
382	      pts.push({ x: tx, y: ty + 8 });
383	      return pts;
384	    };
385	
386	    const drawBolt = () => {
387	      g.clear();
388	      const pts = makePts(tx + Phaser.Math.Between(-25, 25));
389	      g.lineStyle(44, 0xffaa00, 0.09); this._drawPolyline(g, pts);
390	      g.lineStyle(22, 0xffcc00, 0.32); this._drawPolyline(g, pts);
391	      g.lineStyle(9,  0xffee44, 0.80); this._drawPolyline(g, pts);
392	      g.lineStyle(3,  0xffffff, 1.00); this._drawPolyline(g, pts);
393	      [3, 7, 11].forEach(bi => {
394	        if (bi >= pts.length - 1) return;
395	        const bp = pts[bi]!;
396	        const dir = Math.random() < 0.5 ? 1 : -1;
397	        const len = Phaser.Math.Between(55, 105);
398	        const bPts = [
399	          { x: bp.x, y: bp.y },
400	          { x: bp.x + dir * len * 0.35 + Phaser.Math.Between(-18, 18), y: bp.y + len * 0.33 },
401	          { x: bp.x + dir * len * 0.68 + Phaser.Math.Between(-12, 12), y: bp.y + len * 0.65 },
402	          { x: bp.x + dir * len + Phaser.Math.Between(-8, 8),          y: bp.y + len },
403	        ];
404	        g.lineStyle(9,   0xffcc00, 0.40); this._drawPolyline(g, bPts);
405	        g.lineStyle(3,   0xffee44, 0.75); this._drawPolyline(g, bPts);
406	        g.lineStyle(1.5, 0xffffff, 0.90); this._drawPolyline(g, bPts);
407	      });
408	    };
409	
410	    drawBolt();
411	    [50, 100, 150, 200].forEach(delay => {
412	      scene.time.delayedCall(delay, () => {
413	        if (!scene.sys.isActive() || !g.active) return;
414	        drawBolt();
415	      });
416	    });
417	
418	    scene.tweens.add({
419	      targets: g, alpha: 0, delay: 240, duration: 380, ease: 'Quad.easeOut',
420	      onComplete: () => g.destroy(),
421	    });
422	
423	    const impact = scene.add.graphics().setDepth(308);
424	    impact.fillStyle(0xffee00, 0.7);
425	    impact.fillCircle(tx, ty, 55);
426	    scene.tweens.add({
427	      targets: impact, scaleX: 2.8, scaleY: 2.8, alpha: 0,
428	      duration: 500, ease: 'Quad.easeOut',
429	      onComplete: () => impact.destroy(),
430	    });
431	
432	    const ring = scene.add.graphics().setDepth(309);
433	    ring.lineStyle(4, 0xffffff, 1);
434	    ring.strokeCircle(tx, ty, 40);
435	    scene.tweens.add({
436	      targets: ring, scaleX: 3.5, scaleY: 3.5, alpha: 0,
437	      duration: 450, ease: 'Quad.easeOut',
438	      onComplete: () => ring.destroy(),
439	    });
440	
441	    scene.time.delayedCall(180, () => {
442	      if (!scene.sys.isActive()) return;
443	      // 변신 도중 부활로 isGoldForm이 해제됐을 수 있으므로 확인
444	      if (applyGoldSprite && this.isGoldForm) {
445	        api.player.setTexturePrefix('gold_mugi_');
446	      }
447	      this._clearPoops(api, () => true, 20);
448	    });
449	  }
