525	  // ── 공통 유틸 ────────────────────────────────────────────────────────
526	
527	  private _clearPoops(
528	    api: GameSceneAPI,
529	    filter: (p: Phaser.Physics.Arcade.Sprite) => boolean,
530	    pointsPerPoop: number,
531	  ): void {
532	    const { poops, scene } = api;
533	    const targets = (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
534	      .filter(p => p.active && filter(p));
535	
536	    if (targets.length === 0) return;
537	
538	    // 위치를 먼저 저장한 뒤 즉시 재활용 — 피버 타임이 얼어있는 똥을
539	    // 특수 똥으로 변환하는 race condition을 원천 차단
540	    const positions = targets.map(p => ({ x: p.x, y: p.y }));
541	    targets.forEach(p => (p as unknown as PoolablePoopBase).recycle());
542	
543	    // 잽 이펙트는 저장된 위치에서 독립적으로 재생
544	    positions.forEach(({ x, y }) => this._spawnZapEffect(x, y, scene));
545	
546	    scene.time.delayedCall(450, () => {
547	      if (!scene.sys.isActive()) return;
548	      api.addAbilityBonus(positions.length * pointsPerPoop);
549	    });
550	  }
