552	  private _drawPolyline(g: Phaser.GameObjects.Graphics, pts: { x: number; y: number }[]): void {
553	    g.beginPath();
554	    g.moveTo(pts[0]!.x, pts[0]!.y);
555	    for (let i = 1; i < pts.length; i++) g.lineTo(pts[i]!.x, pts[i]!.y);
556	    g.strokePath();
557	  }
558	
559	  private _spawnZapEffect(x: number, y: number, scene: Phaser.Scene): void {
560	    const g = scene.add.graphics().setDepth(206);
561	
562	    const draw = () => {
563	      g.clear();
564	      const sparks = Phaser.Math.Between(3, 5);
565	      for (let i = 0; i < sparks; i++) {
566	        const color = Math.random() < 0.55 ? 0xffee00 : 0xffffff;
567	        g.lineStyle(Phaser.Math.FloatBetween(1.5, 2.5), color, 1);
568	        g.beginPath();
569	        let px = x + Phaser.Math.Between(-7, 7);
570	        let py = y + Phaser.Math.Between(-7, 7);
571	        g.moveTo(px, py);
572	        for (let j = 0; j < 3; j++) {
573	          px += Phaser.Math.Between(-10, 10);
574	          py += Phaser.Math.Between(-10, 10);
575	          g.lineTo(px, py);
576	        }
577	        g.strokePath();
578	      }
579	    };
580	
581	    draw();
582	    const timer = scene.time.addEvent({ delay: 80, repeat: 5, callback: draw });
583	    scene.time.delayedCall(550, () => {
584	      timer.remove();
585	      if (g.active) g.destroy();
586	    });
587	  }
