591	  private _revive(api: GameSceneAPI): void {
592	    this.revivalCharges--;
593	    this.totalRevivalsUsed++;
594	
595	    if (this.isGoldForm) {
596	      this._resetGoldForm(api);
597	    }
598	    this.orbitOrbs.forEach(o => o.gfx.destroy());
599	    this.orbitOrbs = [];
600	    this._destroyRevivalHalo();
601	    this._updateRevivalUI();
602	
603	    const { poops, scene } = api;
604	
605	    // 전체 똥 즉시 제거
606	    (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
607	      .filter(p => p.active)
608	      .forEach(p => (p as unknown as PoolablePoopBase).recycle());
609	
610	    // 화면 중앙으로 이동 + 연꽃 소환
611	    const centerX = scene.scale.width / 2;
612	    api.player.setX(centerX);
613	
614	    api.player.setInvincibleBriefly(2500);
615	    this._playRevivalLotus(centerX, api.player.y, scene);
616	  }
617	
618	  private _playRevivalLotus(px: number, py: number, scene: Phaser.Scene): void {
619	    const LS = 2.2;                // 연꽃 전체 스케일
620	    const cx = px;
621	    const cy = py + 38;            // 플레이어 발 바닥 (displayH=80 → 중심 +40, base offset -2)
622	
623	    // 꽃받침
624	    const base = scene.add.graphics().setDepth(352).setScale(0);
625	    base.fillStyle(0x66bb6a, 0.85); base.fillEllipse(0, 0, 28 * LS, 9 * LS);
626	    base.fillStyle(0x81c784, 0.6);  base.fillEllipse(0, -2 * LS, 16 * LS, 5 * LS);
627	    base.setPosition(cx, cy + 2);
628	    scene.tweens.add({ targets: base, scale: 1, duration: 220, ease: 'Back.easeOut' });
629	
630	    // 금빛 중앙 글로우
631	    const glow = scene.add.graphics().setDepth(353).setScale(0);
632	    glow.fillStyle(0xffd700, 0.20); glow.fillCircle(0, 0, 30 * LS);
633	    glow.fillStyle(0xffe082, 0.35); glow.fillCircle(0, 0, 18 * LS);
634	    glow.fillStyle(0xffffff, 0.55); glow.fillCircle(0, 0,  8 * LS);
635	    glow.setPosition(cx, cy - 14 * LS);
636	    scene.tweens.add({ targets: glow, scale: 1, duration: 320, ease: 'Back.easeOut' });
637	
638	    // sin(t*π) 곡선으로 양 끝 뾰족한 꽃잎 폴리곤
639	    const petalPts = (w: number, h: number): { x: number; y: number }[] => {
640	      const N = 16;
641	      const pts: { x: number; y: number }[] = [];
642	      for (let i = 0; i <= N; i++) {
643	        const t = i / N;
644	        pts.push({ x:  (w / 2) * Math.sin(t * Math.PI), y: h / 2 - t * h });
645	      }
646	      for (let i = N - 1; i >= 0; i--) {
647	        const t = i / N;
648	        pts.push({ x: -(w / 2) * Math.sin(t * Math.PI), y: h / 2 - t * h });
649	      }
650	      return pts;
651	    };
652	
653	    // 꽃잎: 바닥 한 점에서 각도 방향으로 뻗어나가는 옆면 형태
654	    const petalGfxs: Phaser.GameObjects.Graphics[] = [];
655	    LOTUS_DEFS.forEach(([rotDeg, w, h, color, depthOff], idx) => {
656	      const sw = w * LS;
657	      const sh = h * LS;
658	      const rotRad = rotDeg * Math.PI / 180;
659	      const ppx = cx + Math.sin(rotRad) * (sh / 2);
660	      const ppy = (cy + 2) - Math.cos(rotRad) * (sh / 2);
661	
662	      const g = scene.add.graphics().setDepth(353 + depthOff);
663	      g.fillStyle(color, 0.92);
664	      g.fillPoints(petalPts(sw, sh), true);
665	      g.fillStyle(0xffffff, 0.45);
666	      g.fillPoints(petalPts(sw * 0.35, sh * 0.65), true);
667	      g.fillStyle(0xffd700, 0.18);
668	      g.fillEllipse(0, -(sh * 0.3), sw * 0.55, sh * 0.22);
669	      g.setPosition(ppx, ppy).setRotation(rotRad).setScale(0);
670	
671	      scene.tweens.add({ targets: g, scale: 1, delay: idx * 40, duration: 280, ease: 'Back.easeOut' });
672	      petalGfxs.push(g);
673	    });
674	
675	    // 수술
676	    const stamen = scene.add.graphics().setDepth(359).setScale(0);
677	    stamen.fillStyle(0xffd700, 1); stamen.fillCircle(0, 0, 5 * LS);
678	    stamen.fillStyle(0xffff99, 0.9); stamen.fillCircle(0, 0, 3 * LS);
679	    stamen.fillStyle(0xffffff, 0.7); stamen.fillCircle(-1 * LS, -1.5 * LS, 1.5 * LS);
680	    stamen.setPosition(cx, cy - 20 * LS);
681	    scene.tweens.add({
682	      targets: stamen, scale: 1,
683	      delay: LOTUS_DEFS.length * 40 - 20, duration: 220, ease: 'Back.easeOut',
684	    });
685	
686	    // 900ms 후 조용히 페이드아웃
687	    const allObjs: Phaser.GameObjects.Graphics[] = [...petalGfxs, glow, base, stamen];
688	    scene.time.delayedCall(900, () => {
689	      if (!scene.sys.isActive()) return;
690	      allObjs.forEach(obj => {
691	        scene.tweens.add({
692	          targets: obj, alpha: 0,
693	          duration: 500, ease: 'Quad.easeIn',
694	          onComplete: () => { if (obj.active) obj.destroy(); },
695	        });
696	      });
697	    });
698	  }
699	
700	  // ── 부활 후광 ─────────────────────────────────────────────────────────
701	
702	  private _createRevivalHalo(api: GameSceneAPI): void {
703	    const { scene, player } = api;
704	    player.setDepth(5); // 후광보다 위에 렌더링되도록
705	    const hx = player.x;
706	    const hy = player.y - 28; // 얼굴 가리지 않게 아래로 살짝
707	
708	    // 외곽 부드러운 글로우 (depth 3 < player depth 5)
709	    this.revivalHaloOuter = scene.add.image(hx, hy, 'glow_dot')
710	      .setDepth(3)
711	      .setBlendMode(Phaser.BlendModes.ADD)
712	      .setTint(0xffffff)
713	      .setScale(1.5)
714	      .setAlpha(0.35);
715	
716	    // 내부 약간 따뜻한 글로우 (depth 4 < player depth 5)
717	    this.revivalHaloInner = scene.add.image(hx, hy, 'glow_dot')
718	      .setDepth(4)
719	      .setBlendMode(Phaser.BlendModes.ADD)
720	      .setTint(0xffeedd)
721	      .setScale(0.75)
722	      .setAlpha(0.65);
723	
724	    scene.tweens.add({
725	      targets: this.revivalHaloOuter,
726	      alpha: { from: 0.2, to: 0.50 },
727	      scale: { from: 1.3, to: 1.7 },
728	      yoyo: true, repeat: -1, duration: 1100, ease: 'Sine.easeInOut',
729	    });
730	    scene.tweens.add({
731	      targets: this.revivalHaloInner,
732	      alpha: { from: 0.45, to: 0.80 },
733	      yoyo: true, repeat: -1, duration: 1100, ease: 'Sine.easeInOut',
734	    });
735	  }
736	
737	  private _updateRevivalHalo(px: number, py: number): void {
738	    const hy = py - 28;
739	    this.revivalHaloOuter?.setPosition(px, hy);
740	    this.revivalHaloInner?.setPosition(px, hy);
