743	  private _destroyRevivalHalo(): void {
744	    this.revivalHaloOuter?.destroy();
745	    this.revivalHaloInner?.destroy();
746	    this.revivalHaloOuter = null;
747	    this.revivalHaloInner = null;
748	  }
