750	  private _playRechargeGlow(api: GameSceneAPI): void {
751	    const { scene, player } = api;
752	    const g = scene.add.graphics().setDepth(320);
753	    g.lineStyle(4, 0xff88cc, 1);
754	    g.strokeCircle(player.x, player.y, 30);
755	    scene.tweens.add({
756	      targets: g, scaleX: 2.5, scaleY: 2.5, alpha: 0,
757	      duration: 500, ease: 'Quad.easeOut',
758	      onComplete: () => g.destroy(),
759	    });
760	    if (!this.revivalHaloOuter) {
761	      this._createRevivalHalo(api);
762	    }
763	  }
764	
765	  // ── 정리 ─────────────────────────────────────────────────────────────
766	
