768	    this.yeoijus.forEach(orb => orb.gfx.destroy());
769	    this.yeoijus = [];
770	    this.orbitOrbs.forEach(o => o.gfx.destroy());
771	    this.orbitOrbs = [];
772	    this._destroyRevivalHalo();
